package render

import (
	"net/netip"
	"strings"
	"testing"

	"go.yaml.in/yaml/v3"
)

func ip(s string) netip.Addr { return netip.MustParseAddr(s) }

const wantNetplanOne = `# managed-by: pvpn
# Generated by pvpn. Do not edit. ` + "`pvpn reconcile`" + ` rewrites this file.
network:
  version: 2
  ethernets:
    eth0:
      addresses:
        - "2a01:4f8:1c1b:a31:1:2:3:4/128":
            lifetime: 0
      routes:
        - to: "::/0"
          via: "fe80::1"
          from: "2a01:4f8:1c1b:a31:1:2:3:4"
          table: 5751
          on-link: true
      routing-policy:
        - to: "::/0"
          mark: 22353  # 0x5751
          table: 5751
          priority: 101
`

func member(iface string, n int, src string) Member {
	return Member{Iface: iface, Table: 5750 + n, Mark: 0x5750 + n, Priority: 100 + n, Addrs: []netip.Addr{ip(src)}, From: ip(src), Gateway: ip("fe80::1")}
}

func TestNetplanGoldenOneMember(t *testing.T) {
	got := string(Netplan([]Device{{Section: "ethernets", ID: "eth0", Members: []Member{member("pvpn-de1", 1, "2a01:4f8:1c1b:a31:1:2:3:4")}}}))
	if got != wantNetplanOne {
		t.Fatalf("got:\n%s\nwant:\n%s", got, wantNetplanOne)
	}
}

func TestNetplanIsValidYAMLAndSorted(t *testing.T) {
	devs := []Device{{Section: "ethernets", ID: "eth0", Members: []Member{
		member("b", 2, "2001:db8::2"), member("a", 1, "2001:db8::1"),
	}}}
	// Rotation: member "a" keeps the old address and adds a candidate.
	devs[0].Members[1].Addrs = []netip.Addr{ip("2001:db8::9"), ip("2001:db8::1")}
	out := Netplan(devs)
	var doc struct {
		Network struct {
			Version   int `yaml:"version"`
			Ethernets map[string]struct {
				Addresses []map[string]map[string]any `yaml:"addresses"`
				Routes    []map[string]any            `yaml:"routes"`
				Policy    []map[string]any            `yaml:"routing-policy"`
			} `yaml:"ethernets"`
		} `yaml:"network"`
	}
	if err := yaml.Unmarshal(out, &doc); err != nil {
		t.Fatalf("invalid YAML: %v\n%s", err, out)
	}
	e := doc.Network.Ethernets["eth0"]
	if doc.Network.Version != 2 || len(e.Addresses) != 3 || len(e.Routes) != 2 || len(e.Policy) != 2 {
		t.Fatalf("structure: %+v", doc)
	}
	// Members are sorted by interface name: a first.
	if e.Routes[0]["table"] != 5751 || e.Routes[1]["table"] != 5752 {
		t.Fatalf("members not sorted by interface: %+v", e.Routes)
	}
	for _, a := range e.Addresses {
		for k, v := range a {
			if !strings.HasSuffix(k, "/128") || v["lifetime"] != 0 {
				t.Fatalf("address entry %v %v", k, v)
			}
		}
	}
	if string(Netplan(devs)) != string(out) {
		t.Fatal("render is not deterministic")
	}
}

func TestNetplanEmptyAndMultiDevice(t *testing.T) {
	if Netplan(nil) != nil || Netplan([]Device{{Section: "ethernets", ID: "eth0"}}) != nil {
		t.Fatal("no members must give nil (the file is removed)")
	}
	out := string(Netplan([]Device{
		{Section: "vlans", ID: "vlan10", Members: []Member{member("x", 3, "2001:db8::3")}},
		{Section: "ethernets", ID: "eth1", Members: []Member{member("y", 4, "2001:db8::4")}},
		{Section: "ethernets", ID: "eth 0", Members: []Member{member("z", 5, "2001:db8::5")}},
	}))
	var doc map[string]any
	if err := yaml.Unmarshal([]byte(out), &doc); err != nil {
		t.Fatalf("invalid YAML: %v\n%s", err, out)
	}
	if !strings.Contains(out, "  ethernets:\n    \"eth 0\":") || !strings.Contains(out, "    eth1:") || !strings.Contains(out, "  vlans:\n    vlan10:") {
		t.Fatalf("sections or quoting wrong:\n%s", out)
	}
	if strings.Count(out, "  ethernets:") != 1 {
		t.Fatal("ethernets section repeated")
	}
}

const wantWG = `# managed-by = pvpn
# group = germany
# server = DE#520

[Interface]
PrivateKey = PRIV
Address = 10.2.0.2/32, 2a07:b944::2:2/128
Table = off
FwMark = 0x5751
SaveConfig = false
PreUp = ip -6 addr change 2a01:4f8:1c1b:a31:1:2:3:4/128 dev eth0 noprefixroute preferred_lft 0

[Peer]
PublicKey = PUB
Endpoint = [2001:ac8:36:5e::10]:51820
AllowedIPs = 0.0.0.0/0, ::/0
PersistentKeepalive = 25
`

func wgFixture() WG {
	return WG{Iface: "pvpn-de1", Group: "germany", Server: "DE#520", PrivateKey: "PRIV", Mark: 0x5751, Device: "eth0",
		SourceIP: ip("2a01:4f8:1c1b:a31:1:2:3:4"), PeerPublicKey: "PUB", Endpoint: ip("2001:ac8:36:5e::10")}
}

func TestWireGuardGolden(t *testing.T) {
	if got := WireGuard(wgFixture()); got != wantWG {
		t.Fatalf("got:\n%s\nwant:\n%s", got, wantWG)
	}
}

func TestWireGuardHasNoOldHooksOrDNS(t *testing.T) {
	got := WireGuard(wgFixture())
	for _, bad := range []string{"DNS", "ip -6 route", "ip -6 rule", "PostDown", "addr replace", "addr del", "addr add", "ListenPort"} {
		if strings.Contains(got, bad) {
			t.Errorf("file must not contain %q", bad)
		}
	}
	if strings.Count(got, "PreUp") != 1 {
		t.Error("exactly one PreUp command expected")
	}
}

func TestParseWG(t *testing.T) {
	m := ParseWG(wantWG)
	if !m.Managed || m.Group != "germany" || m.Server != "DE#520" || m.PrivateKey != "PRIV" || m.PeerKey != "PUB" || m.Endpoint != "[2001:ac8:36:5e::10]:51820" {
		t.Fatalf("meta: %+v", m)
	}
	// Keys with '=' padding must survive.
	m = ParseWG("# managed-by = pvpn\n[Interface]\nPrivateKey = abc+/def=\n")
	if m.PrivateKey != "abc+/def=" {
		t.Fatalf("key: %q", m.PrivateKey)
	}
	if ParseWG("[Interface]\nPrivateKey = x\n").Managed {
		t.Fatal("file without header must not be managed")
	}
	if ParseWG("").Managed {
		t.Fatal("empty file must not be managed")
	}
}

func TestDropIn(t *testing.T) {
	d := DropIn()
	for _, w := range []string{"Requires=systemd-networkd-wait-online.service", "After=network-online.target systemd-networkd-wait-online.service", "Wants=network-online.target", "[Unit]"} {
		if !strings.Contains(d, w) {
			t.Errorf("drop-in lacks %q", w)
		}
	}
}
